components.css:
.ds-badge-severity { display: inline-block; font-size: 9px; font-weight: 700; letter-spacing: 0.08em; padding: 2px 6px; border-radius: 3px; background: transparent; }
.ds-badge-critical { color: #E83D3D; border: 1px solid #E83D3D; background: rgba(232,61,61,0.15); }
.ds-badge-high { color: #FF8C42; border: 1px solid #FF8C42; background: rgba(255,140,66,0.1); }
.ds-badge-low { color: #FFCC00; border: 1px solid #FFCC00; background: rgba(255,204,0,0.08); }

.ds-btn-primary { background: #E83D3D; color: #FFFFFF; border: 1px solid #E83D3D; border-radius: 8px; padding: 8px 16px; font-family: 'Share Tech Mono', monospace; font-size: 12px; letter-spacing: 0.08em; cursor: pointer; transition: background 0.2s, border-color 0.2s; }
.ds-btn-primary:hover { background: #c93030; border-color: #c93030; }
.ds-btn-primary:active { transform: scale(0.98); }

.ds-input { background: #000000; border: 1px solid #333333; color: #FFFFFF; padding: 8px 12px; font-family: 'Share Tech Mono', monospace; font-size: 13px; border-radius: 8px; outline: none; transition: border-color 0.2s; width: 100%; box-sizing: border-box; }
.ds-input:focus { border-color: #E83D3D; }
.ds-input::placeholder { color: #626262; }

.ds-nav-item { background: transparent; border: none; border-left: 2px solid transparent; color: #626262; padding: 10px 12px; font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 0.08em; cursor: pointer; text-align: left; border-radius: 0 8px 8px 0; transition: color 0.2s, border-left-color 0.2s, background 0.2s; width: 100%; }
.ds-nav-item:hover { color: #FFFFFF; background: rgba(255,255,255,0.04); }
.ds-nav-item.active { background: rgba(232,61,61,0.08); color: #FFFFFF; border-left-color: #E83D3D; }
